# Check if variable should be ignored based on context
should_ignore_variable(var) {
    # Ignore Chef default attributes with null values (common pattern)
    endswith(var.name, "]")
    startswith(var.name, "default[")
    var.value.ir_type == "Null"
} else {
    # Ignore Ansible variables with double underscores in name (common for defaults)
    glitch_lib.contains(var.name, "__")
}

