    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password in configuration file - Password fields should not be empty. (CWE-258)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    all_vars := glitch_lib.all_variables(parent)
    var := all_vars[_]

    # Skip variables that should be ignored
    not should_ignore_variable(var)

    name_contains_password_keyword(var.name)

    check_empty_value(var.value)

    result := {
