import data.glitch_lib
import future.keywords.in

password_keywords := {"password", "pwd", "passphrase", "secret", "credential", "api_key", "token", "auth_key", "key", "activationkey"}

check_empty_value(value) {
    value.ir_type == "String"
    value.value == ""
} else {
    value.ir_type == "Null"
} else {
    value.ir_type == "Undef"
}

name_contains_password_keyword(name) {
    some keyword in password_keywords
    glitch_lib.contains(lower(name), keyword)
}

# Check for empty password variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    all_vars := glitch_lib.all_variables(parent)
    var := all_vars[_]

    name_contains_password_keyword(var.name)

    check_empty_value(var.value)

    # Filter out false positives for Chef attributes that are clearly not passwords
    not is_chef_false_positive(var.name)

    result := {
        "type": "sec_empty_pass",
        "element": var,
        "path": parent.path,
        "description": "Empty password in configuration file - Password variables should not be empty. (CWE-258)"
    }
}

# Check for empty password attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    all_attrs := glitch_lib.all_attributes(parent)
    attr := all_attrs[_]

    name_contains_password_keyword(attr.name)

    check_empty_value(attr.value)

    # Filter out false positives for Chef attributes that are clearly not passwords
    not is_chef_false_positive(attr.name)

    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password in configuration file - Password fields should not be empty. (CWE-258)"
    }
}

# Check for empty password in atomic units (resources/tasks)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    all_units := glitch_lib.all_atomic_units(parent)
    unit := all_units[_]

    unit_attrs := glitch_lib.all_attributes(unit)
    attr := unit_attrs[_]

    name_contains_password_keyword(attr.name)

    check_empty_value(attr.value)

    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password in configuration file - Password fields should not be empty. (CWE-258)"
    }
}

# Check for empty password in function calls
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, node])
    node.ir_type == "FunctionCall"

    name_contains_password_keyword(node.name)

    some arg in node.args
    check_empty_value(arg)

    result := {
        "type": "sec_empty_pass",
        "element": node,
        "path": parent.path,
        "description": "Empty password used in function call - Password arguments should not be empty. (CWE-258)"
    }
}

# Helper to identify Chef false positives
is_chef_false_positive(name) {
    # Chef attributes like sslclientkey are file paths, not passwords
    endswith(name, "sslclientkey")
} else {
    # Chef attributes like proxy_password might be configuration flags, not actual passwords
    # We check if the attribute is in a yum configuration context (common false positive)
    contains(name, "yum")
    contains(name, "main")
    contains(name, "proxy")
}

